from __future__ import annotations

"""Composite continuation token for a cross-partition query.

A single global cursor cannot describe where a fanned-out query left off,
because each physical range advances independently and at a different pace.
The token here is composite: it carries one position per range that still has
rows left. A range that has been fully drained is dropped from the token, so an
empty token means the whole query is exhausted.

Wire format is an opaque base64 blob over JSON. Tests treat it as opaque except
when they round-trip it, so the exact bytes do not matter as long as decode is
the inverse of encode.
"""

import base64
import json
from dataclasses import dataclass


@dataclass(frozen=True)
class RangePosition:
    """How far a single range has been read (next index to emit)."""

    range_id: str
    offset: int

    def advanced(self, by: int) -> "RangePosition":
        return RangePosition(range_id=self.range_id, offset=self.offset + by)


@dataclass(frozen=True)
class CompositeToken:
    """One position per range that still has rows to emit."""

    positions: tuple[RangePosition, ...]

    def is_empty(self) -> bool:
        return len(self.positions) == 0

    def offset_for(self, range_id: str) -> int:
        for pos in self.positions:
            if pos.range_id == range_id:
                return pos.offset
        return 0

    def has_range(self, range_id: str) -> bool:
        return any(pos.range_id == range_id for pos in self.positions)

    def range_ids(self) -> list[str]:
        return [pos.range_id for pos in self.positions]

    def as_dict(self) -> dict[str, int]:
        return {pos.range_id: pos.offset for pos in self.positions}


def empty_token() -> CompositeToken:
    return CompositeToken(positions=())


def token_from_offsets(offsets: dict[str, int]) -> CompositeToken:
    """Build a composite token from a {range_id: offset} mapping."""

    positions = tuple(
        RangePosition(range_id=rid, offset=off) for rid, off in offsets.items()
    )
    return CompositeToken(positions=positions)


def encode_token(token: CompositeToken | None) -> str | None:
    """Serialize a composite token to an opaque string (None when exhausted)."""

    if token is None or token.is_empty():
        return None
    body = {"v": 1, "ranges": token.as_dict()}
    raw = json.dumps(body, sort_keys=True).encode("utf-8")
    return base64.urlsafe_b64encode(raw).decode("ascii")


def decode_token(blob: str | None) -> CompositeToken:
    """Parse an opaque token string back into a composite token."""

    if blob is None or blob == "":
        return empty_token()
    raw = base64.urlsafe_b64decode(blob.encode("ascii"))
    body = json.loads(raw.decode("utf-8"))
    ranges = body.get("ranges", {})
    return token_from_offsets({str(rid): int(off) for rid, off in ranges.items()})


def merge_positions(positions: list[RangePosition]) -> CompositeToken:
    """Collapse a list of per-range positions into a token.

    Ranges with the same id are not expected; the last one wins if seen.
    """

    by_id: dict[str, int] = {}
    for pos in positions:
        by_id[pos.range_id] = pos.offset
    return token_from_offsets(by_id)


def describe_token(token: CompositeToken) -> str:
    if token.is_empty():
        return "<exhausted>"
    parts = [f"{pos.range_id}@{pos.offset}" for pos in token.positions]
    return ", ".join(parts)

