from __future__ import annotations

"""Page a cross-partition query and produce the next continuation token.

The pager fans the query out across every range, asks each range for the rows
it can give starting from where the incoming token left it, fills the page up
to ``max_item_count``, and hands back the rows plus a token the caller passes to
the next ``next_page`` call. Draining the pager (calling until the token comes
back exhausted) must return every matching document exactly once, ordered by
order_key across all ranges.
"""

from dataclasses import dataclass

from continuation_token import (
    CompositeToken,
    RangePosition,
    decode_token,
    empty_token,
    encode_token,
    merge_positions,
)
from partition_executor import RangeResult, execute_range, range_has_more
from partition_store import PartitionRange, PartitionStore
from query_records import Document, QueryPredicate, sort_by_order_key


@dataclass(frozen=True)
class Page:
    documents: tuple[Document, ...]
    continuation: str | None

    def is_last(self) -> bool:
        return self.continuation is None

    def order_keys(self) -> list[int]:
        return [doc.order_key for doc in self.documents]

    def doc_ids(self) -> list[str]:
        return [doc.doc_id for doc in self.documents]

    def size(self) -> int:
        return len(self.documents)


class CrossPartitionPager:
    def __init__(
        self,
        store: PartitionStore,
        predicate: QueryPredicate,
        max_item_count: int,
    ) -> None:
        if max_item_count <= 0:
            raise ValueError("max_item_count must be positive")
        self._predicate = predicate
        self._max_item_count = max_item_count
        self._ranges: list[PartitionRange] = store.build_ranges(predicate)

    @property
    def ranges(self) -> list[PartitionRange]:
        return list(self._ranges)

    def first_page(self) -> Page:
        return self.next_page(None)

    def next_page(self, continuation: str | None) -> Page:
        """Produce one page and the token to resume from."""

        token = decode_token(continuation)
        cursor = self._resume_offset(token)

        collected: list[Document] = []
        last_position: RangePosition | None = None

        for part in self._ranges:
            budget = self._max_item_count - len(collected)
            if budget <= 0:
                break
            result = execute_range(part, cursor, budget)
            collected.extend(result.documents)
            last_position = result.position()

        ordered = sort_by_order_key(collected)
        next_token = self._build_next_token(last_position)
        return Page(
            documents=tuple(ordered),
            continuation=encode_token(next_token),
        )

    def _resume_offset(self, token: CompositeToken) -> int:
        """Where to resume reading the ranges this page."""

        if token.is_empty():
            return 0
        return token.positions[0].offset

    def _build_next_token(self, last_position: RangePosition | None) -> CompositeToken:
        """Carry forward where the fan-out left off."""

        if last_position is None:
            return empty_token()
        if not self._position_has_more(last_position):
            return empty_token()
        return merge_positions([last_position])

    def _position_has_more(self, position: RangePosition) -> bool:
        for part in self._ranges:
            if part.range_id == position.range_id:
                return range_has_more(part, position.offset)
        return False

    def page_count_estimate(self) -> int:
        total = sum(part.size() for part in self._ranges)
        if total == 0:
            return 0
        return (total + self._max_item_count - 1) // self._max_item_count

    def total_matching(self) -> int:
        return sum(part.size() for part in self._ranges)

