from __future__ import annotations

"""Run the query against a single physical range from a given offset.

The cross-partition pager fans out across ranges and asks each range for the
rows it can produce starting at the offset recorded in the continuation token.
A range returns a small result: the rows it emitted plus the offset a later
page should resume from. Whether a row is taken is bounded by the page budget
the pager hands down (how many rows the page still has room for).
"""

from dataclasses import dataclass

from continuation_token import RangePosition
from partition_store import PartitionRange
from query_records import Document


@dataclass(frozen=True)
class RangeResult:
    """Rows emitted from one range on one page, with the resume position."""

    range_id: str
    documents: tuple[Document, ...]
    next_offset: int
    drained: bool

    def emitted(self) -> int:
        return len(self.documents)

    def position(self) -> RangePosition:
        return RangePosition(range_id=self.range_id, offset=self.next_offset)


def execute_range(
    part: PartitionRange,
    start_offset: int,
    budget: int,
) -> RangeResult:
    """Emit up to ``budget`` rows from one range starting at ``start_offset``.

    The returned ``next_offset`` is where the next page must resume this range.
    ``drained`` says whether this range has nothing left after the slice. A
    budget of zero emits nothing and leaves the offset untouched.
    """

    if budget < 0:
        raise ValueError("budget must be non-negative")
    if start_offset < 0:
        raise ValueError("start_offset must be non-negative")

    take = max(0, budget)
    slice_docs = part.slice_from(start_offset, take)
    next_offset = start_offset + len(slice_docs)
    drained = part.is_exhausted(next_offset)
    return RangeResult(
        range_id=part.range_id,
        documents=tuple(slice_docs),
        next_offset=next_offset,
        drained=drained,
    )


def remaining_in_range(part: PartitionRange, start_offset: int) -> int:
    """How many rows the range still holds from this offset onward."""

    return max(0, part.size() - start_offset)


def range_has_more(part: PartitionRange, start_offset: int) -> bool:
    return remaining_in_range(part, start_offset) > 0


def peek_next(part: PartitionRange, start_offset: int) -> Document | None:
    if start_offset >= part.size():
        return None
    return part.at(start_offset)


def total_remaining(parts: list[PartitionRange], offsets: dict[str, int]) -> int:
    """Sum of rows still pending across all ranges given current offsets."""

    total = 0
    for part in parts:
        total += remaining_in_range(part, offsets.get(part.range_id, 0))
    return total


def any_range_has_more(parts: list[PartitionRange], offsets: dict[str, int]) -> bool:
    for part in parts:
        if range_has_more(part, offsets.get(part.range_id, 0)):
            return True
    return False

