from __future__ import annotations

"""In-memory model of a container's physical partitions.

A Cosmos container is split into physical partition ranges. A cross-partition
query fans out and runs once per range; each range produces its own ordered
stream of matching documents. This module holds, per range, the documents that
already match the predicate, sorted by ``order_key``. Each range is identified
by a stable ``range_id`` so a position taken in one page can be lined back up
against the same range on the next page.
"""

from dataclasses import dataclass, field

from query_records import Document, QueryPredicate, sort_by_order_key


@dataclass(frozen=True)
class PartitionRange:
    """One physical partition range and its matching documents in order."""

    range_id: str
    documents: tuple[Document, ...]

    def size(self) -> int:
        return len(self.documents)

    def at(self, index: int) -> Document:
        return self.documents[index]

    def slice_from(self, index: int, count: int) -> list[Document]:
        return list(self.documents[index : index + count])

    def is_exhausted(self, index: int) -> bool:
        return index >= len(self.documents)


@dataclass
class PartitionStore:
    """The set of physical ranges that back one container, in a fixed order."""

    _ranges: dict[str, list[Document]] = field(default_factory=dict)
    _order: list[str] = field(default_factory=list)

    def add(self, range_id: str, documents: list[Document]) -> None:
        if range_id not in self._ranges:
            self._order.append(range_id)
        self._ranges[range_id] = list(documents)

    def range_ids(self) -> list[str]:
        """Range ids in their stable fan-out order."""

        return list(self._order)

    def documents_in(self, range_id: str) -> list[Document]:
        return list(self._ranges.get(range_id, []))

    def count(self) -> int:
        return len(self._order)

    def total_documents(self) -> int:
        return sum(len(docs) for docs in self._ranges.values())

    def build_ranges(self, predicate: QueryPredicate) -> list[PartitionRange]:
        """Materialize each range as the predicate-matching docs in order.

        This is what the executor fans the query out across. Each range filters
        its own documents and sorts them by order_key, mirroring how an index
        scan inside a single physical partition would emit rows.
        """

        ranges: list[PartitionRange] = []
        for range_id in self._order:
            matching = [doc for doc in self._ranges[range_id] if doc.matches(predicate)]
            ordered = sort_by_order_key(matching)
            ranges.append(PartitionRange(range_id=range_id, documents=tuple(ordered)))
        return ranges

    def matching_count(self, predicate: QueryPredicate) -> int:
        total = 0
        for docs in self._ranges.values():
            total += sum(1 for doc in docs if doc.matches(predicate))
        return total


def build_store(layout: dict[str, list[Document]]) -> PartitionStore:
    """Build a store from a {range_id: [documents]} mapping.

    Insertion order of the mapping fixes the fan-out order of the ranges.
    """

    store = PartitionStore()
    for range_id, docs in layout.items():
        store.add(range_id, docs)
    return store


def empty_store() -> PartitionStore:
    return PartitionStore()

