"""Convenience client over the pager: open a query, drain it, summarize.

This is the surface application code calls. It opens a paged query against a
store, walks the continuation tokens to completion, and offers small helpers to
inspect what came back. A safety bound stops a runaway loop if paging never
reports exhaustion, so a token bug surfaces as wrong rows rather than a hang.
"""

from dataclasses import dataclass

from cross_partition_pager import CrossPartitionPager, Page
from partition_store import PartitionStore
from query_records import Document, QueryPredicate, predicate_for


MAX_PAGES_GUARD = 10_000


@dataclass
class QueryClient:
    store: PartitionStore

    def open_query(
        self,
        wanted_status: str,
        max_item_count: int,
    ) -> CrossPartitionPager:
        predicate = predicate_for(wanted_status)
        return CrossPartitionPager(self.store, predicate, max_item_count)

    def pages(self, wanted_status: str, max_item_count: int) -> list[Page]:
        """Walk every page to exhaustion and return them in order."""

        pager = self.open_query(wanted_status, max_item_count)
        out: list[Page] = []
        page = pager.first_page()
        out.append(page)
        guard = 0
        while not page.is_last():
            guard += 1
            if guard > MAX_PAGES_GUARD:
                raise RuntimeError("paging did not terminate")
            page = pager.next_page(page.continuation)
            out.append(page)
        return out

    def drain(self, wanted_status: str, max_item_count: int) -> list[Document]:
        """Every matching document across all pages, in emitted order."""

        collected: list[Document] = []
        for page in self.pages(wanted_status, max_item_count):
            collected.extend(page.documents)
        return collected

    def drain_ids(self, wanted_status: str, max_item_count: int) -> list[str]:
        return [doc.doc_id for doc in self.drain(wanted_status, max_item_count)]

    def drain_order_keys(self, wanted_status: str, max_item_count: int) -> list[int]:
        return [doc.order_key for doc in self.drain(wanted_status, max_item_count)]

    def page_sizes(self, wanted_status: str, max_item_count: int) -> list[int]:
        return [page.size() for page in self.pages(wanted_status, max_item_count)]

    def count_distinct_ids(self, wanted_status: str, max_item_count: int) -> int:
        return len(set(self.drain_ids(wanted_status, max_item_count)))

    def has_duplicates(self, wanted_status: str, max_item_count: int) -> bool:
        ids = self.drain_ids(wanted_status, max_item_count)
        return len(ids) != len(set(ids))

    def page_count(self, wanted_status: str, max_item_count: int) -> int:
        return len(self.pages(wanted_status, max_item_count))

    def summarize(self, wanted_status: str, max_item_count: int) -> dict:
        drained = self.drain(wanted_status, max_item_count)
        ids = [doc.doc_id for doc in drained]
        return {
            "wanted_status": wanted_status,
            "max_item_count": max_item_count,
            "row_count": len(ids),
            "distinct_count": len(set(ids)),
            "has_duplicates": len(ids) != len(set(ids)),
            "page_count": self.page_count(wanted_status, max_item_count),
        }


def build_client(store: PartitionStore) -> QueryClient:
    return QueryClient(store=store)


def predicate_label(predicate: QueryPredicate) -> str:
    return predicate.describe()

