from __future__ import annotations

"""Documents and the query predicate used by the cross-partition pager.

A Cosmos container holds JSON documents. Each document carries a partition key
value; the physical layout groups documents into ranges by hashing that key.
The query here is read-only: it selects documents whose ``status`` field equals
a wanted value and returns them ordered by ``order_key`` (a monotonically
increasing per-container sequence the writer stamps on every insert).
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class Document:
    doc_id: str
    partition_key: str
    status: str
    order_key: int
    payload: str = ""

    def __post_init__(self) -> None:
        if not self.doc_id.strip():
            raise ValueError("doc_id is required")
        if not self.partition_key.strip():
            raise ValueError("partition_key is required")
        if self.order_key < 0:
            raise ValueError("order_key must be non-negative")

    def matches(self, predicate: "QueryPredicate") -> bool:
        return predicate.accepts(self)


@dataclass(frozen=True)
class QueryPredicate:
    """SELECT * FROM c WHERE c.status = wanted_status ORDER BY c.order_key."""

    wanted_status: str

    def accepts(self, doc: Document) -> bool:
        return doc.status == self.wanted_status

    def describe(self) -> str:
        return f"status == {self.wanted_status!r}"


def build_document(
    doc_id: str,
    partition_key: str,
    status: str,
    order_key: int,
    payload: str = "",
) -> Document:
    return Document(
        doc_id=doc_id,
        partition_key=partition_key,
        status=status,
        order_key=order_key,
        payload=payload,
    )


def build_documents(specs: list[tuple]) -> list[Document]:
    """Build documents from (doc_id, partition_key, status, order_key) tuples."""

    out: list[Document] = []
    for spec in specs:
        if len(spec) == 4:
            doc_id, pk, status, order_key = spec
            out.append(build_document(doc_id, pk, status, order_key))
        else:
            doc_id, pk, status, order_key, payload = spec
            out.append(build_document(doc_id, pk, status, order_key, payload))
    return out


def predicate_for(wanted_status: str) -> QueryPredicate:
    return QueryPredicate(wanted_status=wanted_status)


def filter_matches(docs: list[Document], predicate: QueryPredicate) -> list[Document]:
    """Documents that satisfy the predicate, in their stored order."""

    return [doc for doc in docs if doc.matches(predicate)]


def sort_by_order_key(docs: list[Document]) -> list[Document]:
    """Stable sort by order_key; ties keep insertion order."""

    return sorted(docs, key=lambda d: d.order_key)


def order_keys(docs: list[Document]) -> list[int]:
    return [doc.order_key for doc in docs]


def doc_ids(docs: list[Document]) -> list[str]:
    return [doc.doc_id for doc in docs]

